<?php
require __DIR__.'/../app/bootstrap.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id)redirect('index.php');
$s=$pdo->prepare("SELECT a.id,a.score,a.mode,a.source_attempt_id,a.test_id,t.title FROM attempts a JOIN tests t ON t.id=a.test_id WHERE a.id=?");$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Resultaat niet gevonden.');}
$s=$pdo->prepare("SELECT COUNT(*) total,SUM(CASE WHEN is_correct=1 THEN 1 ELSE 0 END) correct FROM attempt_answers WHERE attempt_id=?");$s->execute([$id]);$stats=$s->fetch();
?>
<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resultaat</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:700px"><div class="card shadow-sm text-center"><div class="card-body p-5"><h1>Resultaat</h1><p><?=e($r['title'])?></p><div class="display-3 fw-bold"><?=e((string)$r['score'])?>%</div><p class="mt-3"><?=e((string)$stats['correct'])?> van <?=e((string)$stats['total'])?> vragen goed.</p><div class="d-grid gap-2 mt-4"><a class="btn btn-primary" href="quiz.php?id=<?=$r['test_id']?>&new=1">Toets opnieuw maken</a><?php if((int)$stats['correct']<(int)$stats['total']):?><a class="btn btn-warning" href="quiz.php?id=<?=$r['test_id']?>&mode=mistakes&source=<?=$r['id']?>">Alleen mijn fouten oefenen</a><?php endif;?><a class="btn btn-outline-secondary" href="index.php">Terug naar toetsen</a></div></div></div></main></body></html>
